class Solution {
public:
    int sumOfTheDigitsOfHarshadNumber(int x) {
        int temp = x, s = 0;
        while (temp > 0) {
            s += temp % 10;
            temp /= 10;
        }
        return (x % s == 0) ? s : -1;
    }
};

